import{_ as a,o as r,c as t,a3 as i}from"./chunks/framework.B5WAEDB7.js";const o="/assets/images/Xkm5CXz.png",s="/assets/images/C9ioGtn.png",n="/assets/images/krAHLGg.png",l="/assets/images/U3qV33e.png",d="/assets/images/wU8x5Id.png",c="/assets/images/n16iOGk.png",h="/assets/images/fNcl65g.png",u="/assets/images/wXGqG5f.png",v=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"core-concepts/database.md","filePath":"core-concepts/database.md"}'),m={name:"core-concepts/database.md"};function p(g,e,f,b,w,y){return r(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="database" tabindex="-1">Database <a class="header-anchor" href="#database" aria-label="Permalink to &quot;Database&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Key Takeaways</p><ul><li>Understand the core principles of Database.</li><li>Focus on the trade-offs involved in different approaches.</li><li>Keep scalability and performance in mind.</li></ul></div><p align="center"><img src="'+o+'"><br><i><a href="https://www.youtube.com/watch?v=kKjm4ehYiMs">Source: Scaling up to your first 10 million users</a></i></p><h3 id="relational-database-management-system-rdbms" tabindex="-1">Relational database management system (RDBMS) <a class="header-anchor" href="#relational-database-management-system-rdbms" aria-label="Permalink to &quot;Relational database management system (RDBMS)&quot;">​</a></h3><p>A relational database like SQL is a collection of data items organized in tables.</p><p><strong>ACID</strong> is a set of properties of relational database <a href="https://en.wikipedia.org/wiki/Database_transaction" target="_blank" rel="noreferrer">transactions</a>.</p><ul><li><strong>Atomicity</strong> - Each transaction is all or nothing</li><li><strong>Consistency</strong> - Any transaction will bring the database from one valid state to another</li><li><strong>Isolation</strong> - Executing transactions concurrently has the same results as if the transactions were executed serially</li><li><strong>Durability</strong> - Once a transaction has been committed, it will remain so</li></ul><p>There are many techniques to scale a relational database: <strong>master-slave replication</strong>, <strong>master-master replication</strong>, <strong>federation</strong>, <strong>sharding</strong>, <strong>denormalization</strong>, and <strong>SQL tuning</strong>.</p><h4 id="master-slave-replication" tabindex="-1">Master-slave replication <a class="header-anchor" href="#master-slave-replication" aria-label="Permalink to &quot;Master-slave replication&quot;">​</a></h4><p>The master serves reads and writes, replicating writes to one or more slaves, which serve only reads. Slaves can also replicate to additional slaves in a tree-like fashion. If the master goes offline, the system can continue to operate in read-only mode until a slave is promoted to a master or a new master is provisioned.</p><p align="center"><img src="'+s+'"><br><i><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/">Source: Scalability, availability, stability, patterns</a></i></p><h5 id="disadvantage-s-master-slave-replication" tabindex="-1">Disadvantage(s): master-slave replication <a class="header-anchor" href="#disadvantage-s-master-slave-replication" aria-label="Permalink to &quot;Disadvantage(s): master-slave replication&quot;">​</a></h5><ul><li>Additional logic is needed to promote a slave to a master.</li><li>See <a href="#disadvantages-replication">Disadvantage(s): replication</a> for points related to <strong>both</strong> master-slave and master-master.</li></ul><h4 id="master-master-replication" tabindex="-1">Master-master replication <a class="header-anchor" href="#master-master-replication" aria-label="Permalink to &quot;Master-master replication&quot;">​</a></h4><p>Both masters serve reads and writes and coordinate with each other on writes. If either master goes down, the system can continue to operate with both reads and writes.</p><p align="center"><img src="'+n+'"><br><i><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/">Source: Scalability, availability, stability, patterns</a></i></p><h5 id="disadvantage-s-master-master-replication" tabindex="-1">Disadvantage(s): master-master replication <a class="header-anchor" href="#disadvantage-s-master-master-replication" aria-label="Permalink to &quot;Disadvantage(s): master-master replication&quot;">​</a></h5><ul><li>You&#39;ll need a load balancer or you&#39;ll need to make changes to your application logic to determine where to write.</li><li>Most master-master systems are either loosely consistent (violating ACID) or have increased write latency due to synchronization.</li><li>Conflict resolution comes more into play as more write nodes are added and as latency increases.</li><li>See <a href="#disadvantages-replication">Disadvantage(s): replication</a> for points related to <strong>both</strong> master-slave and master-master.</li></ul><h5 id="disadvantage-s-replication" tabindex="-1">Disadvantage(s): replication <a class="header-anchor" href="#disadvantage-s-replication" aria-label="Permalink to &quot;Disadvantage(s): replication&quot;">​</a></h5><ul><li>There is a potential for loss of data if the master fails before any newly written data can be replicated to other nodes.</li><li>Writes are replayed to the read replicas. If there are a lot of writes, the read replicas can get bogged down with replaying writes and can&#39;t do as many reads.</li><li>The more read slaves, the more you have to replicate, which leads to greater replication lag.</li><li>On some systems, writing to the master can spawn multiple threads to write in parallel, whereas read replicas only support writing sequentially with a single thread.</li><li>Replication adds more hardware and additional complexity.</li></ul><h5 id="source-s-and-further-reading-replication" tabindex="-1">Source(s) and further reading: replication <a class="header-anchor" href="#source-s-and-further-reading-replication" aria-label="Permalink to &quot;Source(s) and further reading: replication&quot;">​</a></h5><ul><li><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/" target="_blank" rel="noreferrer">Scalability, availability, stability, patterns</a></li><li><a href="https://en.wikipedia.org/wiki/Multi-master_replication" target="_blank" rel="noreferrer">Multi-master replication</a></li></ul><h4 id="federation" tabindex="-1">Federation <a class="header-anchor" href="#federation" aria-label="Permalink to &quot;Federation&quot;">​</a></h4><p align="center"><img src="'+l+'"><br><i><a href="https://www.youtube.com/watch?v=kKjm4ehYiMs">Source: Scaling up to your first 10 million users</a></i></p><p>Federation (or functional partitioning) splits up databases by function. For example, instead of a single, monolithic database, you could have three databases: <strong>forums</strong>, <strong>users</strong>, and <strong>products</strong>, resulting in less read and write traffic to each database and therefore less replication lag. Smaller databases result in more data that can fit in memory, which in turn results in more cache hits due to improved cache locality. With no single central master serializing writes you can write in parallel, increasing throughput.</p><h5 id="disadvantage-s-federation" tabindex="-1">Disadvantage(s): federation <a class="header-anchor" href="#disadvantage-s-federation" aria-label="Permalink to &quot;Disadvantage(s): federation&quot;">​</a></h5><ul><li>Federation is not effective if your schema requires huge functions or tables.</li><li>You&#39;ll need to update your application logic to determine which database to read and write.</li><li>Joining data from two databases is more complex with a <a href="http://stackoverflow.com/questions/5145637/querying-data-by-joining-two-tables-in-two-database-on-different-servers" target="_blank" rel="noreferrer">server link</a>.</li><li>Federation adds more hardware and additional complexity.</li></ul><h5 id="source-s-and-further-reading-federation" tabindex="-1">Source(s) and further reading: federation <a class="header-anchor" href="#source-s-and-further-reading-federation" aria-label="Permalink to &quot;Source(s) and further reading: federation&quot;">​</a></h5><ul><li><a href="https://www.youtube.com/watch?v=kKjm4ehYiMs" target="_blank" rel="noreferrer">Scaling up to your first 10 million users</a></li></ul><h4 id="sharding" tabindex="-1">Sharding <a class="header-anchor" href="#sharding" aria-label="Permalink to &quot;Sharding&quot;">​</a></h4><p align="center"><img src="'+d+'"><br><i><a href="http://www.slideshare.net/jboner/scalability-availability-stability-patterns/">Source: Scalability, availability, stability, patterns</a></i></p><p>Sharding distributes data across different databases such that each database can only manage a subset of the data. Taking a users database as an example, as the number of users increases, more shards are added to the cluster.</p><p>Similar to the advantages of <a href="#federation">federation</a>, sharding results in less read and write traffic, less replication, and more cache hits. Index size is also reduced, which generally improves performance with faster queries. If one shard goes down, the other shards are still operational, although you&#39;ll want to add some form of replication to avoid data loss. Like federation, there is no single central master serializing writes, allowing you to write in parallel with increased throughput.</p><p>Common ways to shard a table of users is either through the user&#39;s last name initial or the user&#39;s geographic location.</p><h5 id="disadvantage-s-sharding" tabindex="-1">Disadvantage(s): sharding <a class="header-anchor" href="#disadvantage-s-sharding" aria-label="Permalink to &quot;Disadvantage(s): sharding&quot;">​</a></h5><ul><li>You&#39;ll need to update your application logic to work with shards, which could result in complex SQL queries.</li><li>Data distribution can become lopsided in a shard. For example, a set of power users on a shard could result in increased load to that shard compared to others. <ul><li>Rebalancing adds additional complexity. A sharding function based on <a href="http://www.paperplanes.de/2011/12/9/the-magic-of-consistent-hashing.html" target="_blank" rel="noreferrer">consistent hashing</a> can reduce the amount of transferred data.</li></ul></li><li>Joining data from multiple shards is more complex.</li><li>Sharding adds more hardware and additional complexity.</li></ul><h5 id="source-s-and-further-reading-sharding" tabindex="-1">Source(s) and further reading: sharding <a class="header-anchor" href="#source-s-and-further-reading-sharding" aria-label="Permalink to &quot;Source(s) and further reading: sharding&quot;">​</a></h5><ul><li><a href="http://highscalability.com/blog/2009/8/6/an-unorthodox-approach-to-database-design-the-coming-of-the.html" target="_blank" rel="noreferrer">The coming of the shard</a></li><li><a href="https://en.wikipedia.org/wiki/Shard_(database_architecture)" target="_blank" rel="noreferrer">Shard database architecture</a></li><li><a href="http://www.paperplanes.de/2011/12/9/the-magic-of-consistent-hashing.html" target="_blank" rel="noreferrer">Consistent hashing</a></li></ul><h4 id="denormalization" tabindex="-1">Denormalization <a class="header-anchor" href="#denormalization" aria-label="Permalink to &quot;Denormalization&quot;">​</a></h4><p>Denormalization attempts to improve read performance at the expense of some write performance. Redundant copies of the data are written in multiple tables to avoid expensive joins. Some RDBMS such as <a href="https://en.wikipedia.org/wiki/PostgreSQL" target="_blank" rel="noreferrer">PostgreSQL</a> and Oracle support <a href="https://en.wikipedia.org/wiki/Materialized_view" target="_blank" rel="noreferrer">materialized views</a> which handle the work of storing redundant information and keeping redundant copies consistent.</p><p>Once data becomes distributed with techniques such as <a href="#federation">federation</a> and <a href="#sharding">sharding</a>, managing joins across data centers further increases complexity. Denormalization might circumvent the need for such complex joins.</p><p>In most systems, reads can heavily outnumber writes 100:1 or even 1000:1. A read resulting in a complex database join can be very expensive, spending a significant amount of time on disk operations.</p><h5 id="disadvantage-s-denormalization" tabindex="-1">Disadvantage(s): denormalization <a class="header-anchor" href="#disadvantage-s-denormalization" aria-label="Permalink to &quot;Disadvantage(s): denormalization&quot;">​</a></h5><ul><li>Data is duplicated.</li><li>Constraints can help redundant copies of information stay in sync, which increases complexity of the database design.</li><li>A denormalized database under heavy write load might perform worse than its normalized counterpart.</li></ul><h6 id="source-s-and-further-reading-denormalization" tabindex="-1">Source(s) and further reading: denormalization <a class="header-anchor" href="#source-s-and-further-reading-denormalization" aria-label="Permalink to &quot;Source(s) and further reading: denormalization&quot;">​</a></h6><ul><li><a href="https://en.wikipedia.org/wiki/Denormalization" target="_blank" rel="noreferrer">Denormalization</a></li></ul><h4 id="sql-tuning" tabindex="-1">SQL tuning <a class="header-anchor" href="#sql-tuning" aria-label="Permalink to &quot;SQL tuning&quot;">​</a></h4><p>SQL tuning is a broad topic and many <a href="https://www.amazon.com/s/ref=nb_sb_noss_2?url=search-alias%3Daps&amp;field-keywords=sql+tuning" target="_blank" rel="noreferrer">books</a> have been written as reference.</p><p>It&#39;s important to <strong>benchmark</strong> and <strong>profile</strong> to simulate and uncover bottlenecks.</p><ul><li><strong>Benchmark</strong> - Simulate high-load situations with tools such as <a href="http://httpd.apache.org/docs/2.2/programs/ab.html" target="_blank" rel="noreferrer">ab</a>.</li><li><strong>Profile</strong> - Enable tools such as the <a href="http://dev.mysql.com/doc/refman/5.7/en/slow-query-log.html" target="_blank" rel="noreferrer">slow query log</a> to help track performance issues.</li></ul><p>Benchmarking and profiling might point you to the following optimizations.</p><h5 id="tighten-up-the-schema" tabindex="-1">Tighten up the schema <a class="header-anchor" href="#tighten-up-the-schema" aria-label="Permalink to &quot;Tighten up the schema&quot;">​</a></h5><ul><li>MySQL dumps to disk in contiguous blocks for fast access.</li><li>Use <code>CHAR</code> instead of <code>VARCHAR</code> for fixed-length fields. <ul><li><code>CHAR</code> effectively allows for fast, random access, whereas with <code>VARCHAR</code>, you must find the end of a string before moving onto the next one.</li></ul></li><li>Use <code>TEXT</code> for large blocks of text such as blog posts. <code>TEXT</code> also allows for boolean searches. Using a <code>TEXT</code> field results in storing a pointer on disk that is used to locate the text block.</li><li>Use <code>INT</code> for larger numbers up to 2^32 or 4 billion.</li><li>Use <code>DECIMAL</code> for currency to avoid floating point representation errors.</li><li>Avoid storing large <code>BLOBS</code>, store the location of where to get the object instead.</li><li><code>VARCHAR(255)</code> is the largest number of characters that can be counted in an 8 bit number, often maximizing the use of a byte in some RDBMS.</li><li>Set the <code>NOT NULL</code> constraint where applicable to <a href="http://stackoverflow.com/questions/1017239/how-do-null-values-affect-performance-in-a-database-search" target="_blank" rel="noreferrer">improve search performance</a>.</li></ul><h5 id="use-good-indices" tabindex="-1">Use good indices <a class="header-anchor" href="#use-good-indices" aria-label="Permalink to &quot;Use good indices&quot;">​</a></h5><ul><li>Columns that you are querying (<code>SELECT</code>, <code>GROUP BY</code>, <code>ORDER BY</code>, <code>JOIN</code>) could be faster with indices.</li><li>Indices are usually represented as self-balancing <a href="https://en.wikipedia.org/wiki/B-tree" target="_blank" rel="noreferrer">B-tree</a> that keeps data sorted and allows searches, sequential access, insertions, and deletions in logarithmic time.</li><li>Placing an index can keep the data in memory, requiring more space.</li><li>Writes could also be slower since the index also needs to be updated.</li><li>When loading large amounts of data, it might be faster to disable indices, load the data, then rebuild the indices.</li></ul><h5 id="avoid-expensive-joins" tabindex="-1">Avoid expensive joins <a class="header-anchor" href="#avoid-expensive-joins" aria-label="Permalink to &quot;Avoid expensive joins&quot;">​</a></h5><ul><li><a href="#denormalization">Denormalize</a> where performance demands it.</li></ul><h5 id="partition-tables" tabindex="-1">Partition tables <a class="header-anchor" href="#partition-tables" aria-label="Permalink to &quot;Partition tables&quot;">​</a></h5><ul><li>Break up a table by putting hot spots in a separate table to help keep it in memory.</li></ul><h5 id="tune-the-query-cache" tabindex="-1">Tune the query cache <a class="header-anchor" href="#tune-the-query-cache" aria-label="Permalink to &quot;Tune the query cache&quot;">​</a></h5><ul><li>In some cases, the <a href="https://dev.mysql.com/doc/refman/5.7/en/query-cache.html" target="_blank" rel="noreferrer">query cache</a> could lead to <a href="https://www.percona.com/blog/2016/10/12/mysql-5-7-performance-tuning-immediately-after-installation/" target="_blank" rel="noreferrer">performance issues</a>.</li></ul><h5 id="source-s-and-further-reading-sql-tuning" tabindex="-1">Source(s) and further reading: SQL tuning <a class="header-anchor" href="#source-s-and-further-reading-sql-tuning" aria-label="Permalink to &quot;Source(s) and further reading: SQL tuning&quot;">​</a></h5><ul><li><a href="http://aiddroid.com/10-tips-optimizing-mysql-queries-dont-suck/" target="_blank" rel="noreferrer">Tips for optimizing MySQL queries</a></li><li><a href="http://stackoverflow.com/questions/1217466/is-there-a-good-reason-i-see-varchar255-used-so-often-as-opposed-to-another-l" target="_blank" rel="noreferrer">Is there a good reason i see VARCHAR(255) used so often?</a></li><li><a href="http://stackoverflow.com/questions/1017239/how-do-null-values-affect-performance-in-a-database-search" target="_blank" rel="noreferrer">How do null values affect performance?</a></li><li><a href="http://dev.mysql.com/doc/refman/5.7/en/slow-query-log.html" target="_blank" rel="noreferrer">Slow query log</a></li></ul><h3 id="nosql" tabindex="-1">NoSQL <a class="header-anchor" href="#nosql" aria-label="Permalink to &quot;NoSQL&quot;">​</a></h3><p>NoSQL is a collection of data items represented in a <strong>key-value store</strong>, <strong>document store</strong>, <strong>wide column store</strong>, or a <strong>graph database</strong>. Data is denormalized, and joins are generally done in the application code. Most NoSQL stores lack true ACID transactions and favor <a href="#eventual-consistency">eventual consistency</a>.</p><p><strong>BASE</strong> is often used to describe the properties of NoSQL databases. In comparison with the <a href="/core-concepts/availability-vs-consistency.html#cap-theorem">CAP Theorem</a>, BASE chooses availability over consistency.</p><ul><li><strong>Basically available</strong> - the system guarantees availability.</li><li><strong>Soft state</strong> - the state of the system may change over time, even without input.</li><li><strong>Eventual consistency</strong> - the system will become consistent over a period of time, given that the system doesn&#39;t receive input during that period.</li></ul><p>In addition to choosing between <a href="#sql-or-nosql">SQL or NoSQL</a>, it is helpful to understand which type of NoSQL database best fits your use case(s). We&#39;ll review <strong>key-value stores</strong>, <strong>document stores</strong>, <strong>wide column stores</strong>, and <strong>graph databases</strong> in the next section.</p><h4 id="key-value-store" tabindex="-1">Key-value store <a class="header-anchor" href="#key-value-store" aria-label="Permalink to &quot;Key-value store&quot;">​</a></h4><blockquote><p>Abstraction: hash table</p></blockquote><p>A key-value store generally allows for O(1) reads and writes and is often backed by memory or SSD. Data stores can maintain keys in <a href="https://en.wikipedia.org/wiki/Lexicographical_order" target="_blank" rel="noreferrer">lexicographic order</a>, allowing efficient retrieval of key ranges. Key-value stores can allow for storing of metadata with a value.</p><p>Key-value stores provide high performance and are often used for simple data models or for rapidly-changing data, such as an in-memory cache layer. Since they offer only a limited set of operations, complexity is shifted to the application layer if additional operations are needed.</p><p>A key-value store is the basis for more complex systems such as a document store, and in some cases, a graph database.</p><h5 id="source-s-and-further-reading-key-value-store" tabindex="-1">Source(s) and further reading: key-value store <a class="header-anchor" href="#source-s-and-further-reading-key-value-store" aria-label="Permalink to &quot;Source(s) and further reading: key-value store&quot;">​</a></h5><ul><li><a href="https://en.wikipedia.org/wiki/Key-value_database" target="_blank" rel="noreferrer">Key-value database</a></li><li><a href="http://stackoverflow.com/questions/4056093/what-are-the-disadvantages-of-using-a-key-value-table-over-nullable-columns-or" target="_blank" rel="noreferrer">Disadvantages of key-value stores</a></li><li><a href="http://qnimate.com/overview-of-redis-architecture/" target="_blank" rel="noreferrer">Redis architecture</a></li><li><a href="https://adayinthelifeof.nl/2011/02/06/memcache-internals/" target="_blank" rel="noreferrer">Memcached architecture</a></li></ul><h4 id="document-store" tabindex="-1">Document store <a class="header-anchor" href="#document-store" aria-label="Permalink to &quot;Document store&quot;">​</a></h4><blockquote><p>Abstraction: key-value store with documents stored as values</p></blockquote><p>A document store is centered around documents (XML, JSON, binary, etc), where a document stores all information for a given object. Document stores provide APIs or a query language to query based on the internal structure of the document itself. <em>Note, many key-value stores include features for working with a value&#39;s metadata, blurring the lines between these two storage types.</em></p><p>Based on the underlying implementation, documents are organized by collections, tags, metadata, or directories. Although documents can be organized or grouped together, documents may have fields that are completely different from each other.</p><p>Some document stores like <a href="https://www.mongodb.com/mongodb-architecture" target="_blank" rel="noreferrer">MongoDB</a> and <a href="https://blog.couchdb.org/2016/08/01/couchdb-2-0-architecture/" target="_blank" rel="noreferrer">CouchDB</a> also provide a SQL-like language to perform complex queries. <a href="http://www.read.seas.harvard.edu/~kohler/class/cs239-w08/decandia07dynamo.pdf" target="_blank" rel="noreferrer">DynamoDB</a> supports both key-values and documents.</p><p>Document stores provide high flexibility and are often used for working with occasionally changing data.</p><h5 id="source-s-and-further-reading-document-store" tabindex="-1">Source(s) and further reading: document store <a class="header-anchor" href="#source-s-and-further-reading-document-store" aria-label="Permalink to &quot;Source(s) and further reading: document store&quot;">​</a></h5><ul><li><a href="https://en.wikipedia.org/wiki/Document-oriented_database" target="_blank" rel="noreferrer">Document-oriented database</a></li><li><a href="https://www.mongodb.com/mongodb-architecture" target="_blank" rel="noreferrer">MongoDB architecture</a></li><li><a href="https://blog.couchdb.org/2016/08/01/couchdb-2-0-architecture/" target="_blank" rel="noreferrer">CouchDB architecture</a></li><li><a href="https://www.elastic.co/blog/found-elasticsearch-from-the-bottom-up" target="_blank" rel="noreferrer">Elasticsearch architecture</a></li></ul><h4 id="wide-column-store" tabindex="-1">Wide column store <a class="header-anchor" href="#wide-column-store" aria-label="Permalink to &quot;Wide column store&quot;">​</a></h4><p align="center"><img src="'+c+'"><br><i><a href="http://blog.grio.com/2015/11/sql-nosql-a-brief-history.html">Source: SQL &amp; NoSQL, a brief history</a></i></p><blockquote><p>Abstraction: nested map <code>ColumnFamily&lt;RowKey, Columns&lt;ColKey, Value, Timestamp&gt;&gt;</code></p></blockquote><p>A wide column store&#39;s basic unit of data is a column (name/value pair). A column can be grouped in column families (analogous to a SQL table). Super column families further group column families. You can access each column independently with a row key, and columns with the same row key form a row. Each value contains a timestamp for versioning and for conflict resolution.</p><p>Google introduced <a href="http://www.read.seas.harvard.edu/~kohler/class/cs239-w08/chang06bigtable.pdf" target="_blank" rel="noreferrer">Bigtable</a> as the first wide column store, which influenced the open-source <a href="https://www.edureka.co/blog/hbase-architecture/" target="_blank" rel="noreferrer">HBase</a> often-used in the Hadoop ecosystem, and <a href="http://docs.datastax.com/en/cassandra/3.0/cassandra/architecture/archIntro.html" target="_blank" rel="noreferrer">Cassandra</a> from Facebook. Stores such as BigTable, HBase, and Cassandra maintain keys in lexicographic order, allowing efficient retrieval of selective key ranges.</p><p>Wide column stores offer high availability and high scalability. They are often used for very large data sets.</p><h5 id="source-s-and-further-reading-wide-column-store" tabindex="-1">Source(s) and further reading: wide column store <a class="header-anchor" href="#source-s-and-further-reading-wide-column-store" aria-label="Permalink to &quot;Source(s) and further reading: wide column store&quot;">​</a></h5><ul><li><a href="http://blog.grio.com/2015/11/sql-nosql-a-brief-history.html" target="_blank" rel="noreferrer">SQL &amp; NoSQL, a brief history</a></li><li><a href="http://www.read.seas.harvard.edu/~kohler/class/cs239-w08/chang06bigtable.pdf" target="_blank" rel="noreferrer">Bigtable architecture</a></li><li><a href="https://www.edureka.co/blog/hbase-architecture/" target="_blank" rel="noreferrer">HBase architecture</a></li><li><a href="http://docs.datastax.com/en/cassandra/3.0/cassandra/architecture/archIntro.html" target="_blank" rel="noreferrer">Cassandra architecture</a></li></ul><h4 id="graph-database" tabindex="-1">Graph database <a class="header-anchor" href="#graph-database" aria-label="Permalink to &quot;Graph database&quot;">​</a></h4><p align="center"><img src="'+h+'"><br><i><a href="https://en.wikipedia.org/wiki/File:GraphDatabase_PropertyGraph.png">Source: Graph database</a></i></p><blockquote><p>Abstraction: graph</p></blockquote><p>In a graph database, each node is a record and each arc is a relationship between two nodes. Graph databases are optimized to represent complex relationships with many foreign keys or many-to-many relationships.</p><p>Graphs databases offer high performance for data models with complex relationships, such as a social network. They are relatively new and are not yet widely-used; it might be more difficult to find development tools and resources. Many graphs can only be accessed with <a href="#representational-state-transfer-rest">REST APIs</a>.</p><h5 id="source-s-and-further-reading-graph" tabindex="-1">Source(s) and further reading: graph <a class="header-anchor" href="#source-s-and-further-reading-graph" aria-label="Permalink to &quot;Source(s) and further reading: graph&quot;">​</a></h5><ul><li><a href="https://en.wikipedia.org/wiki/Graph_database" target="_blank" rel="noreferrer">Graph database</a></li><li><a href="https://neo4j.com/" target="_blank" rel="noreferrer">Neo4j</a></li><li><a href="https://blog.twitter.com/2010/introducing-flockdb" target="_blank" rel="noreferrer">FlockDB</a></li></ul><h4 id="source-s-and-further-reading-nosql" tabindex="-1">Source(s) and further reading: NoSQL <a class="header-anchor" href="#source-s-and-further-reading-nosql" aria-label="Permalink to &quot;Source(s) and further reading: NoSQL&quot;">​</a></h4><ul><li><a href="http://stackoverflow.com/questions/3342497/explanation-of-base-terminology" target="_blank" rel="noreferrer">Explanation of base terminology</a></li><li><a href="https://medium.com/baqend-blog/nosql-databases-a-survey-and-decision-guidance-ea7823a822d#.wskogqenq" target="_blank" rel="noreferrer">NoSQL databases a survey and decision guidance</a></li><li><a href="https://web.archive.org/web/20220602114024/https://www.lecloud.net/post/7994751381/scalability-for-dummies-part-2-database" target="_blank" rel="noreferrer">Scalability</a></li><li><a href="https://www.youtube.com/watch?v=qI_g07C_Q5I" target="_blank" rel="noreferrer">Introduction to NoSQL</a></li><li><a href="http://horicky.blogspot.com/2009/11/nosql-patterns.html" target="_blank" rel="noreferrer">NoSQL patterns</a></li></ul><h3 id="sql-or-nosql" tabindex="-1">SQL or NoSQL <a class="header-anchor" href="#sql-or-nosql" aria-label="Permalink to &quot;SQL or NoSQL&quot;">​</a></h3><p align="center"><img src="'+u+'"><br><i><a href="https://www.infoq.com/articles/Transition-RDBMS-NoSQL/">Source: Transitioning from RDBMS to NoSQL</a></i></p><p>Reasons for <strong>SQL</strong>:</p><ul><li>Structured data</li><li>Strict schema</li><li>Relational data</li><li>Need for complex joins</li><li>Transactions</li><li>Clear patterns for scaling</li><li>More established: developers, community, code, tools, etc</li><li>Lookups by index are very fast</li></ul><p>Reasons for <strong>NoSQL</strong>:</p><ul><li>Semi-structured data</li><li>Dynamic or flexible schema</li><li>Non-relational data</li><li>No need for complex joins</li><li>Store many TB (or PB) of data</li><li>Very data intensive workload</li><li>Very high throughput for IOPS</li></ul><p>Sample data well-suited for NoSQL:</p><ul><li>Rapid ingest of clickstream and log data</li><li>Leaderboard or scoring data</li><li>Temporary data, such as a shopping cart</li><li>Frequently accessed (&#39;hot&#39;) tables</li><li>Metadata/lookup tables</li></ul><h5 id="source-s-and-further-reading-sql-or-nosql" tabindex="-1">Source(s) and further reading: SQL or NoSQL <a class="header-anchor" href="#source-s-and-further-reading-sql-or-nosql" aria-label="Permalink to &quot;Source(s) and further reading: SQL or NoSQL&quot;">​</a></h5><ul><li><a href="https://www.youtube.com/watch?v=kKjm4ehYiMs" target="_blank" rel="noreferrer">Scaling up to your first 10 million users</a></li><li><a href="https://www.sitepoint.com/sql-vs-nosql-differences/" target="_blank" rel="noreferrer">SQL vs NoSQL differences</a></li></ul>',110)])])}const q=a(m,[["render",p]]);export{v as __pageData,q as default};
